export function chooseRandomItem(t){const e=Math.floor(Math.random()*t.length);return{index:e,item:t[e]}}export function delay(t,e){return window.setTimeout(e,t)}export function randomizeArray(t){const e=[...t],r=[];for(;e.length;){const t=Math.floor(Math.random()*e.length);r.push(e.splice(t,1)[0])}return r}export function repeatArray(t,e){return Array.from({length:e},(()=>t)).flat()}export function removeRepeatingItems(t){return Array.from(new Set(t))}export function formatAsTime(t){const e=[[36e5,"h"],[6e4,"m"],[1e3,"s"]];for(const[r,n]of e)if(t>=r){const e=Math.trunc(t/r),o=t-e*r;return`${e}${n}${o?formatAsTime(o):""}`}return`${Math.trunc(t)}ms`}export function numberWithCommas(t){return t?.toLocaleString("en-US",{maximumFractionDigits:0})}export function convertToStandardFormat(t){let e=`${t}`.replace(/,/g,"");if(!/^[0-9.]+$/.test(e))return t;e=Math.round(Number(e));const r=`${e}`.length,n=[[15,1e15,"aa"],[12,1e12,"T"],[9,1e9,"B"],[6,1e6,"M"],[4,1e3,"K"]].find((([t])=>r>t));return n?`${(e/n[1]).toFixed(2)} ${n[2]}`:numberWithCommas(e)}export function getDirectionVector(t,e=1,r=1,n=!0){const o=Math.sin(t*e)+Math.sin(t*r);let a=o/Math.abs(o);return n&&(a*=a>=0?e:r),a}